params.command:
$ErrorActionPreference='Stop'
$relay=Join-Path $env:USERPROFILE 'HeavenBridgeRepo'
$tmp=Join-Path $env:USERPROFILE 'mhw-branch-reconcile'
if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }
$url=(git -C $relay remote get-url origin).Trim()
git clone --no-local $relay $tmp | Out-Null
git -C $tmp remote set-url origin $url
git -C $tmp fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune
$rows=@()
$branches=git -C $tmp for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object { $_ -ne 'origin/HEAD' }
foreach($rb in $branches){
  $b=$rb -replace '^origin/',''
  if($b -eq 'main'){ continue }
  $counts=(git -C $tmp rev-list --left-right --count "origin/main...origin/$b").Trim() -split '\s+'
  $rows += [pscustomobject]@{branch=$b;main_only=[int]$counts[0];branch_only=[int]$counts[1]}
}
[pscustomobject]@{repo=$tmp;count=$rows.Count;rows=$rows} | ConvertTo-Json -Depth 5 -Compress
